import {WORLD,START,BATTERY_X,CONTAINERS,createRun,nearby,interact,tick,validSave} from './engine.mjs';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d');
const KEY='dead-signal-save-v1';let run=createRun(),screen='shelter',paused=false,sound=false,audio=null,last=0,time=0,radioUntil=0,tutorialUntil=0,storageOK=true,saved=null,keys={left:false,right:false},cam=0,viewWidth=960;
try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(validSave(s))saved=s;}catch{storageOK=false;}
const resetMovement=()=>{keys.left=keys.right=false;$('left').classList.remove('held');$('right').classList.remove('held');};
function show(name){screen=name;['shelter','expedition','complete'].forEach(n=>$(n).hidden=n!==name);resetMovement();window.scrollTo(0,0);}
function base(){const powered=!!saved;$('shelter').classList.toggle('powered',powered);$('power-label').textContent=powered?'ПИТАНИЕ ВОССТАНОВЛЕНО':'ПИТАНИЕ ОТСУТСТВУЕТ';$('shelter-copy').innerHTML=powered?'Свет горит. Рация снова работает.<br>В эфире появился чей-то голос.':'Город молчит. Рация садится.<br>Нужен аккумулятор из старых гаражей.';$('go').innerHTML=powered?'ПОВТОРИТЬ ВЫЛАЗКУ <span>↗</span>':'ВЫЙТИ В ГОРОД <span>↗</span>';$('saved-note').textContent=powered?'✓ Аккумулятор установлен · Глава 01 пройдена':'';$('restart').hidden=!powered;$('footer-state').textContent=storageOK?'СОХРАНЕНИЕ НА ЭТОМ УСТРОЙСТВЕ':'СОХРАНЕНИЕ НЕДОСТУПНО';show('shelter');}
function beep(freq=240,duration=.09,volume=.025){if(!sound||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
function radio(message,duration=6){$('radio-text').textContent=message;$('radio').hidden=false;radioUntil=time+duration;beep(150,.18);}
function start(){run=createRun();paused=false;$('pause-overlay').hidden=true;$('radio').hidden=true;$('tutorial').hidden=false;tutorialUntil=time+9;show('expedition');updateHUD();if(audio?.state==='suspended')audio.resume();}
function finish(){saved={version:1,power:true,stash:[...run.items],completedAt:new Date().toISOString()};try{localStorage.setItem(KEY,JSON.stringify(saved));storageOK=true;}catch{storageOK=false;}$('bonus-result').textContent=run.items.filter(x=>x!=='Аккумулятор').join(' · ');$('save-result').textContent=storageOK?'✓ Прогресс сохранён на этом устройстве':'Прогресс доступен до закрытия страницы. Браузер не разрешил сохранение.';show('complete');beep(440,.3);setTimeout(()=>beep(660,.5),250);}
function action(){if(screen!=='expedition'||paused||$('bag').open)return;const r=interact(run);if(r==='complete')finish();if(r==='search'){resetMovement();beep(110,.06);}updateHUD();}
function updateHUD(){const battery=run.items.includes('Аккумулятор'),target=nearby(run);$('objective').textContent=battery?'Вернуться к выходу слева и подключить аккумулятор':'Найти аккумулятор в гараже № 28';$('distance').textContent=battery?'← '+Math.max(0,Math.round((run.x-START)/18))+' М ДО ВЫХОДА':Math.max(0,Math.round((BATTERY_X-run.x)/18))+' М ДО ГАРАЖА';$('bag-count').textContent=run.items.length+'/3';$('interact').disabled=!target||!!run.search;$('interact').textContent=run.search?'ОБЫСК…':target?.id==='exit'?'В УБЕЖИЩЕ ←':target?'ОБЫСКАТЬ [E]':'ПОДОЙДИ БЛИЖЕ';$('hint').style.display=target&&!run.search?'block':'none';$('hint').textContent=target?.id==='exit'?'← Выход в убежище':target?.label||'';$('progress-wrap').hidden=!run.search;if(run.search){const box=CONTAINERS.find(c=>c.id===run.search);$('progress').style.width=Math.min(100,run.searchTime/box.duration*100)+'%';}}
function pause(value){if(screen!=='expedition')return;paused=value;resetMovement();$('pause-overlay').hidden=!value;}
$('go').onclick=start;$('restart').onclick=()=>{try{localStorage.removeItem(KEY);}catch{}saved=null;base();};$('to-base').onclick=base;$('pause').onclick=()=>pause(true);$('resume').onclick=()=>pause(false);$('leave').onclick=()=>{paused=false;base();};$('interact').onclick=action;
document.querySelector('.brand').onclick=e=>{e.preventDefault();if(screen==='expedition')pause(true);else base();};
$('sound').onclick=()=>{try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();sound=!sound;$('sound').textContent=sound?'ЗВУК: ВКЛ':'ЗВУК: ВЫКЛ';$('sound').setAttribute('aria-pressed',sound);$('sound').setAttribute('aria-label',sound?'Выключить звук':'Включить звук');beep(330);}catch{$('sound').textContent='ЗВУК НЕДОСТУПЕН';}};
for(const id of ['left','right']){const el=$(id);el.addEventListener('pointerdown',e=>{e.preventDefault();if(paused||screen!=='expedition')return;keys[id]=true;el.classList.add('held');el.setPointerCapture(e.pointerId);});for(const event of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(event,()=>{keys[id]=false;el.classList.remove('held');});}
window.addEventListener('keydown',e=>{if(screen!=='expedition'||$('bag').open)return;const k=e.key.toLowerCase();if(['arrowleft','arrowright','a','d','ф','в','e','у',' '].includes(k))e.preventDefault();if(k==='escape'){pause(!paused);return;}if(paused)return;if(['arrowleft','a','ф'].includes(k))keys.left=true;if(['arrowright','d','в'].includes(k))keys.right=true;if(['e','у',' '].includes(k)&&!e.repeat)action();});
window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(['arrowleft','a','ф'].includes(k))keys.left=false;if(['arrowright','d','в'].includes(k))keys.right=false;});window.addEventListener('blur',()=>{resetMovement();if(screen==='expedition')pause(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden&&screen==='expedition')pause(true);});
$('bag-toggle').onclick=()=>{resetMovement();$('bag-items').replaceChildren();if(!run.items.length)$('bag-items').textContent='Пока пусто. Осмотри ящики в гаражах.';for(const item of run.items){const d=document.createElement('div');d.textContent=(item==='Аккумулятор'?'▣ ':item==='Бинт'?'✚ ':'⚒ ')+item+' ×1';$('bag-items').append(d);}$('bag').showModal();};$('bag-close').onclick=()=>$('bag').close();
// Seeded geometry keeps the city consistent on every frame.
function rand(seed){let v=Math.sin(seed*127.1+311.7)*43758.5453;return v-Math.floor(v);}function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h);}function line(x,y,x2,y2,c,width=1){ctx.strokeStyle=c;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x2,y2);ctx.stroke();}
function label(text,x,y,color='#c2ccba',size=10){ctx.fillStyle=color;ctx.font=size+'px monospace';ctx.fillText(text,Math.round(x),Math.round(y));}
function building(x,y,w,h,seed){rect(x,y,w,h,'#414b4d');rect(x+3,y+3,w-6,h-3,'#465152');for(let iy=0;iy<h/22-1;iy++)for(let ix=0;ix<w/17-1;ix++){const wx=x+9+ix*17,wy=y+12+iy*22;rect(wx,wy,8,12,rand(seed+ix+iy*12)>.97?'#97977a':'#2f3c40');rect(wx+1,wy,2,12,'#5b6562');}for(let j=0;j<8;j++)line(x,y+j*43,x+w,y+j*43,'#394649');}
function garage(x,index){const open=index===7||index===2||index===5;const c=['#4f5a54','#4c5351','#555b54','#47585c'][index%4];rect(x-4,208,344,8,'#282e2b');rect(x,216,330,188,c);rect(x+9,227,312,177,'#303a37');if(open){rect(x+16,233,298,171,'#171f1c');rect(x+30,246,270,8,'#4d5544');rect(x+30,291,270,8,'#4d5544');rect(x+30,337,270,8,'#4d5544');for(let k=0;k<8;k++){const xx=x+35+k*32;rect(xx,260+Math.floor(rand(index+k)*2)*45,23,29,'#434b39');rect(xx+3,264+Math.floor(rand(index+k)*2)*45,17,2,'#6a7054');}rect(x+26,342,50,60,'#535a43');rect(x+218,360,60,42,'#303d36');}else{rect(x+15,234,300,170,c);for(let k=0;k<38;k++)line(x+17+k*8,235,x+17+k*8,402,'#39433d');line(x+165,235,x+165,404,'#232d28',3);rect(x+154,314,7,3,'#93927d');rect(x+170,314,7,3,'#93927d');}for(let k=0;k<34;k++){let xx=x+rand(index*100+k)*320,yy=225+rand(k*17+index)*170;rect(xx,yy,2+rand(k)*9,2+rand(index+k)*13,'#554b3b');}rect(x-9,203,350,5,'#71786c');line(x-9,210,x+340,210,'#18251f',3);label(index===7?'28':String(21+index),x+155,225,'#afb29a',11);}
function crate(c){const opened=run.opened.includes(c.id),x=c.x-23,y=375;rect(x,y,46,29,opened?'#3d4437':'#606b4b');rect(x+3,y+4,40,4,'#87916a');line(x+7,y,x+7,y+29,'#333e2e',3);line(x+38,y,x+38,y+29,'#333e2e',3);rect(x+20,y+11,7,5,'#b1b59a');if(!opened){const glow=.4+.3*Math.sin(time*3);ctx.globalAlpha=glow;rect(x+20,y-17,5,5,'#e1edbd');ctx.globalAlpha=1;label(c.id==='battery'?'АККУМУЛЯТОР':'ПРИПАСЫ',x-11,y-25,'#bcc9a0',8);}else label('ОБЫСКАНО',x-5,y-10,'#7b8970',8);}
function player(){const x=run.x,y=405,walking=(keys.left||keys.right)&&!run.search&&!paused;const step=walking?Math.sin(time*12):0;ctx.save();ctx.translate(Math.round(x),y);ctx.scale(run.facing,1);ctx.fillStyle='#0b161260';ctx.beginPath();ctx.ellipse(0,3,21,5,0,0,Math.PI*2);ctx.fill();rect(-12,-49,12,28,'#566042');rect(-15,-45,3,21,'#79805a');rect(-10,-42,8,2,'#93936c');rect(-8,-53,20,31,'#26332f');rect(-5,-52,5,27,'#39473b');rect(7,-45,7,22,'#303d34');rect(9,-27,7,6,'#8e927a');rect(-4,-68,17,16,'#1f2c28');rect(8,-62,9,9,'#969a83');rect(13,-59,5,6,'#8c8f77');rect(-4,-69,16,7,'#263730');rect(9,-52,8,4,'#1c2c25');const a=Math.round(step*7);rect(-7,-23,9,20+a,'#374336');rect(4,-23,9,20-a,'#414a38');rect(-9,-5+a,13,6,'#1b2924');rect(4,-5-a,15,6,'#17251f');if(run.search){rect(14,-37,18,6,'#394638');rect(28,-37,5,5,'#a5a68a');}if(run.items.includes('Аккумулятор')){rect(-19,-24,11,15,'#83865a');rect(-17,-28,7,4,'#a0a77d');}ctx.restore();}
function draw(){const narrow=window.innerWidth<=600&&window.innerHeight>520;viewWidth=narrow?640:960;const height=480;canvas.width=viewWidth;canvas.height=height;ctx.imageSmoothingEnabled=false;cam=Math.max(0,Math.min(WORLD-viewWidth,run.x-viewWidth*.4));
 const sky=ctx.createLinearGradient(0,0,0,390);sky.addColorStop(0,'#53656b');sky.addColorStop(1,'#8b9994');ctx.fillStyle=sky;ctx.fillRect(0,0,viewWidth,height);
 ctx.save();ctx.translate(-Math.round(cam*.21),0);for(let i=0;i<11;i++){let h=130+rand(i+4)*90;building(i*180-40,210-h,160,h,i*77);}ctx.restore();
 ctx.fillStyle='#90a39e44';ctx.fillRect(0,100,viewWidth,130);ctx.save();ctx.translate(-Math.round(cam*.55),0);for(let i=0;i<16;i++){const x=i*190-50;line(x,190,x-12,310,'#3b4e48',4);line(x-2,213,x-28,189,'#3b4e48',2);line(x-2,230,x+28,203,'#3b4e48',2);}ctx.restore();
 ctx.save();ctx.translate(-Math.round(cam),0);rect(0,394,WORLD,86,'#343f37');for(let i=0;i<900;i++){const x=rand(i+300)*WORLD,y=406+rand(i+7)*74;rect(x,y,1+rand(i+4)*5,1,rand(i+8)>.6?'#657268':'#25342e');}for(let i=0;i<40;i++){const x=rand(i+41)*WORLD,y=410+rand(i+81)*65;rect(x,y,20+rand(i)*90,3,'#6c817c66');line(x,y,x+30,y,'#a1aca055');}
 for(let i=0;i<9;i++)garage(420+i*345,i);
 // Concrete exit, wire fence and weathered signs.
 rect(0,220,255,185,'#5a665d');rect(65,260,120,145,'#24352b');rect(75,270,100,135,'#3d4b38');rect(158,332,7,4,'#a5ad88');rect(82,230,90,17,'#26362a');label('УБЕЖИЩЕ',89,242,'#b0bda0',10);label('← ВОЗВРАЩЕНИЕ',47,211,'#c5cbb5',9);line(220,160,220,403,'#404f42',5);line(224,164,400,190,'#2c3a33');for(let i=0;i<13;i++)line(230+i*13,175+i*2,230+i*13,330,'#657365',1);
 for(let i=0;i<22;i++){let x=i*169+rand(i)*90;for(let k=0;k<7;k++)line(x+k*3,406,x+k*3-3,396-rand(i+k)*14,'#647050',1);}
 CONTAINERS.forEach(crate);player();ctx.restore();
 // Cold rain in the foreground; no allocations of image assets in the loop.
 ctx.globalAlpha=.23;for(let i=0;i<90;i++){const x=(rand(i+98)*viewWidth-time*35)%viewWidth,y=(rand(i+21)*height+time*180)%height;line(x,y,x-4,y+13,'#d4e3db',1);}ctx.globalAlpha=1;
 const fade=ctx.createLinearGradient(0,415,0,480);fade.addColorStop(0,'#15291b00');fade.addColorStop(1,'#0e1d15aa');ctx.fillStyle=fade;ctx.fillRect(0,415,viewWidth,65);
}
let lastFoot=0,ambientTriggered=false;function frame(ms){const dt=last?Math.min((ms-last)/1000,.05):0;last=ms;time+=dt;if(screen==='expedition'){if(!paused&&!$('bag').open){const direction=Number(keys.right)-Number(keys.left);const acquired=tick(run,dt,direction);if(acquired==='Аккумулятор'){radio('…если слышишь… не выключай…',7);beep(480,.2);}else if(acquired){radio(acquired+' найден. Можно забрать и другие припасы.',3);}if(direction&&!run.search&&time-lastFoot>.4){lastFoot=time;beep(60+rand(time)*30,.045,.008);}if(run.x>450&&!ambientTriggered){ambientTriggered=true;radio('Боксы справа. Ищи гараж с номером 28.',5);}updateHUD();}draw();if(time>tutorialUntil)$('tutorial').hidden=true;if(time>radioUntil)$('radio').hidden=true;}requestAnimationFrame(frame);}base();requestAnimationFrame(frame);
